BarSeriesConfig.definition:
interface BarSeriesConfig {
  /** Key in data for this series */
  dataKey: string;
  /** Display name (shown in tooltip & legend) */
  label: string;
  /** Bar fill colour */
  color?: string;
}

ChartActiveHandler.definition:
type ChartActiveHandler = (
  datum: Record<string, unknown> | null,
  index: number | null,
) => void;

ChartSummaryItem.definition:
interface ChartSummaryItem {
  /** Label shown above the value */
  label: string;
  /** Formatted value to display */
  value: string | number;
}
